INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6460075, 958874, 10785, '<td valign="top">Nice scene but it is really lacking any interest. People having a romantic dinner or something would have added interest.</td>', 'Nice scene but it is really lacking any interest. People having a romantic dinner or something would have added interest.', '2011-07-03 21:44:16.000000', NULL, 1),
(6460076, 958406, 10785, '<td valign="top">I think that yuou exposed the shadows real well but then failed to bring out any details in the skin through post processing. Her skin is very bright and somewhat blown out.</td>', 'I think that yuou exposed the shadows real well but then failed to bring out any details in the skin through post processing. Her skin is very bright and somewhat blown out.', '2011-07-03 21:48:22.000000', NULL, 1),
(6460078, 957776, 10785, '<td valign="top">I think you did everything right for this picture. Great depth of field, great sharpness and proper exposure. The one thing going against it is the sepia. If this were entered in any other challenge I would have scored it higher. But the sepia really turns the diamonds yellow and that''s not what one wants to see in a diamond ring.</td>', 'I think you did everything right for this picture. Great depth of field, great sharpness and proper exposure. The one thing going against it is the sepia. If this were entered in any other challenge I would have scored it higher. But the sepia really turns the diamonds yellow and that''s not what one wants to see in a diamond ring.', '2011-07-03 21:50:59.000000', NULL, 1),
